// A Rust crate with no dependencies, for native desktop interfaces (egui, iced, Slint), image
// rendering and tools: every set is a static, resolved without allocation. Dimensions are logical
// pixels.
import packageInfo from "../../package.json" with { type: "json" };
import {
  fixed,
  hex8,
  pascal,
  screaming,
  type NativeTokens,
  type Rgba,
} from "./native.ts";
import { rustVector } from "./vectors.ts";
import { rustComponents } from "./components-native.ts";

const HEADER =
  "// GENERATED by nddev-opennetwork-design-system (`just generate`). Do not edit.\n";
const snake = (id: string): string => id.replace(/[.-]/g, "_").toLowerCase();
// A struct literal (not a const fn call), so a reference to it in a slice is promoted to 'static.
const rgba = (c: Rgba): string => {
  const [a, r, g, b] = [0, 2, 4, 6].map((i) => hex8(c).slice(i, i + 2));
  return `Color { r: 0x${r ?? ""}, g: 0x${g ?? ""}, b: 0x${b ?? ""}, a: 0x${a ?? ""} }`;
};
const doc = (d: string | undefined, indent = "    "): string =>
  d ? `${indent}/// ${d.replace(/\s+/g, " ")}\n` : "";
const f = (n: number): string => fixed(n);

function enumOf(name: string, ids: string[], what: string, extra = ""): string {
  const variants = ids.map((x) => pascal(x));
  return `/// ${what}
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ${name} {
${variants.map((v) => `    ${v},`).join("\n")}
}

impl ${name} {
    /// Every value, in order.
    pub const ALL: [${name}; ${ids.length}] = [${variants.map((v) => `${name}::${v}`).join(", ")}];

    /// The token id.
    pub const fn id(self) -> &'static str {
        match self {
${ids.map((x, i) => `            ${name}::${variants[i] ?? ""} => "${x}",`).join("\n")}
        }
    }
${extra}}
`;
}

export function emitRust(t: NativeTokens): Map<string, string> {
  const files = new Map<string, string>();
  const combos = t.themes.flatMap((th) =>
    t.directions.map((d) => [th.id, d.id] as const),
  );
  const metricCombos = t.platforms.flatMap((p) =>
    t.densities.map((c) => [p, c] as const),
  );
  const family = (id: string): string => pascal(id.replace(/^font\./, ""));
  const matchScript = (
    fn: (s: NativeTokens["scripts"][number]) => string,
  ): string =>
    `        match self {\n${t.scripts.map((s) => `            Script::${pascal(s.id)} => ${fn(s)},`).join("\n")}\n        }`;

  const tokens = `${HEADER}// The values; lib.rs re-exports them. Not formatted by rustfmt (the generator lays it out).
use core::time::Duration;

${enumOf(
  "Direction",
  t.directions.map((d) => d.id),
  "A direction of NDDev: its accent colours.",
)}
${enumOf(
  "Theme",
  t.themes.map((x) => x.id),
  "A colour theme; the contrast themes answer a request for more contrast.",
  `
    /// Whether the theme draws light content on dark surfaces.
    pub const fn is_dark(self) -> bool {
        match self {
${t.themes.map((x) => `            Theme::${pascal(x.id)} => ${String(x.scheme === "dark")},`).join("\n")}
        }
    }
`,
)}
${enumOf("Platform", t.platforms, "The platform whose sizes, type scale and fonts apply.")}
${enumOf("Density", t.densities, "How tightly controls are laid out.")}
${enumOf("Motion", t.motions, "Standard motion, or reduced: every duration zero.")}
${enumOf(
  "FontFamily",
  t.fonts.map((x) => x.id.replace(/^font\./, "")),
  "A font family token; `font_stack` names its fonts on each platform.",
)}
${enumOf(
  "TypeRole",
  t.type.map((r) => r.role),
  `A text style of the kit.\n${t.type.map((r) => `/// - \`${pascal(r.role)}\`: ${r.description}`).join("\n")}`,
  `
    /// Running text, which takes a script's body leading.
    pub const fn is_body(self) -> bool {
        matches!(self, ${t.type
          .filter((r) => r.body)
          .map((r) => `TypeRole::${pascal(r.role)}`)
          .join(" | ")})
    }
`,
)}
${enumOf(
  "Script",
  t.scripts.map((s) => s.id),
  "The writing system of a text, which adjusts its style.",
  `
    /// The family that replaces the sans family for this script.
    pub const fn family(self) -> FontFamily {
${matchScript((s) => `FontFamily::${family(s.family)}`)}
    }

    /// Whether letter spacing applies (it breaks Arabic joining and has no use in Chinese).
    pub const fn tracks_letters(self) -> bool {
${matchScript((s) => String(s.tracking))}
    }

    /// Whether the script has case, so upper-case styles apply.
    pub const fn has_case(self) -> bool {
${matchScript((s) => String(s.case))}
    }

    /// The line height of running text, where the script needs more than the style's.
    pub const fn body_leading(self) -> Option<f32> {
${matchScript((s) => (s.bodyLeading ? `Some(${f(s.bodyLeading)})` : "None"))}
    }
`,
)}
/// An sRGB colour with 8-bit channels.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Color {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

impl Color {
    /// From 0xRRGGBBAA.
    pub const fn from_rgba(v: u32) -> Self {
        Color { r: (v >> 24) as u8, g: (v >> 16) as u8, b: (v >> 8) as u8, a: v as u8 }
    }

    /// As 0xRRGGBBAA.
    pub const fn to_rgba(self) -> u32 {
        (self.r as u32) << 24 | (self.g as u32) << 16 | (self.b as u32) << 8 | self.a as u32
    }

    /// Channels as 0.0..=1.0 (red, green, blue, alpha).
    pub fn to_f32(self) -> [f32; 4] {
        [self.r, self.g, self.b, self.a].map(|c| f32::from(c) / 255.0)
    }
}

/// Every colour role of one theme in one direction.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Colors {
${t.colors.map((c) => `${doc(c.description)}    pub ${snake(c.id)}: Color,`).join("\n")}
}

impl Colors {
    /// The colours of a theme in a direction.
    pub const fn resolve(theme: Theme, direction: Direction) -> &'static Colors {
        match (theme, direction) {
${combos.map(([th, d]) => `            (Theme::${pascal(th)}, Direction::${pascal(d)}) => &COLORS_${screaming(th)}_${screaming(d)},`).join("\n")}
        }
    }
}

${combos
  .map(
    ([th, d]) =>
      `static COLORS_${screaming(th)}_${screaming(d)}: Colors = Colors {\n${t.colors
        .map((c) => {
          const v = c.values[th]?.[d];
          if (!v) throw new Error(`${c.id} ${th}/${d}`);
          return `    ${snake(c.id)}: ${rgba(v)},`;
        })
        .join("\n")}\n};`,
  )
  .join("\n\n")}

/// Every dimension, in logical pixels, for one platform and density.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Metrics {
${t.dimensions.map((x) => `${doc(x.description)}    pub ${snake(x.id)}: f32,`).join("\n")}
}

impl Metrics {
    pub const fn resolve(platform: Platform, density: Density) -> &'static Metrics {
        match (platform, density) {
${metricCombos.map(([p, c]) => `            (Platform::${pascal(p)}, Density::${pascal(c)}) => &METRICS_${screaming(p)}_${screaming(c)},`).join("\n")}
        }
    }
}

${metricCombos
  .map(
    ([p, c]) =>
      `static METRICS_${screaming(p)}_${screaming(c)}: Metrics = Metrics {\n${t.dimensions
        .map((x) => `    ${snake(x.id)}: ${f(x.values[p]?.[c] ?? 0)},`)
        .join("\n")}\n};`,
  )
  .join("\n\n")}

/// Numbers: opacity, leading, tracking (em), stacking, springs.
pub mod numbers {
${t.numbers.map((n) => `${doc(n.description)}    pub const ${screaming(n.id)}: f32 = ${f(n.value)};${n.unit ? ` // ${n.unit}` : ""}`).join("\n")}
}

/// Font weights (1..=1000).
pub mod weights {
${t.weights.map((w) => `    pub const ${screaming(w.id)}: u16 = ${w.value};`).join("\n")}
}

/// The fonts of a family on a platform, most preferred first.
pub const fn font_stack(family: FontFamily, platform: Platform) -> &'static [&'static str] {
    match (family, platform) {
${t.fonts
  .flatMap((fo) =>
    t.platforms.map(
      (p) =>
        `        (FontFamily::${family(fo.id)}, Platform::${pascal(p)}) => &[${(fo.values[p] ?? []).map((x) => JSON.stringify(x)).join(", ")}],`,
    ),
  )
  .join("\n")}
    }
}

/// Durations.
pub mod durations {
    use super::{Duration, Motion};
${t.durations
  .map(
    (d) =>
      `\n    pub const fn ${snake(d.id)}(motion: Motion) -> Duration {\n        match motion {\n${t.motions
        .map(
          (m) =>
            `            Motion::${pascal(m)} => Duration::from_millis(${Math.round(d.values[m] ?? 0)}),`,
        )
        .join("\n")}\n        }\n    }`,
  )
  .join("\n")}
}

/// Easings as cubic Bezier control points (x1, y1, x2, y2).
pub mod easings {
${t.easings.map((e) => `${doc(e.description)}    pub const ${screaming(e.id)}: [f32; 4] = [${e.value.map(f).join(", ")}];`).join("\n")}
}

/// One layer of a shadow, in logical pixels.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ShadowLayer {
    pub color: Color,
    pub x: f32,
    pub y: f32,
    pub blur: f32,
    pub spread: f32,
    pub inset: bool,
}

/// Elevation shadows per theme.
pub mod shadows {
    use super::{Color, ShadowLayer, Theme};
${t.shadows
  .map(
    (s) =>
      `\n${doc(s.description)}    pub const fn ${snake(s.id)}(theme: Theme) -> &'static [ShadowLayer] {\n        match theme {\n${t.themes
        .map(
          (th) =>
            `            Theme::${pascal(th.id)} => &[${(s.values[th.id] ?? [])
              .map(
                (l) =>
                  `ShadowLayer { color: ${rgba(l.color)}, x: ${f(l.x)}, y: ${f(l.y)}, blur: ${f(l.blur)}, spread: ${f(l.spread)}, inset: ${String(l.inset)} }`,
              )
              .join(", ")}],`,
        )
        .join("\n")}\n        }\n    }`,
  )
  .join("\n")}
}

/// The faces this crate bundles (OFL-1.1, fonts/${t.fontLicense}), with the \`fonts\` feature: the
/// TTF bytes for renderers that load fonts from memory. Chinese and monospace use the system faces.
#[cfg(feature = "fonts")]
pub mod font_files {
    use super::FontFamily;

    /// A bundled face: the family token it serves, its weight, its file name and bytes.
    #[derive(Clone, Copy, Debug)]
    pub struct FontFile {
        pub family: FontFamily,
        pub weight: u16,
        pub file: &'static str,
        pub data: &'static [u8],
    }

    pub static ALL: [FontFile; ${t.bundled.reduce((n, b) => n + b.files.length, 0)}] = [
${t.bundled.flatMap((b) => b.files.map((f) => `        FontFile { family: FontFamily::${family(b.token)}, weight: ${f.weight}, file: "${f.file}", data: include_bytes!("../fonts/${f.file}") },`)).join("\n")}
    ];
}

/// How a stroke ends.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum LineCap {
    Butt,
    Round,
    Square,
}

/// How stroke segments meet.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum LineJoin {
    Miter,
    Round,
    Bevel,
}

/// One shape of a vector: SVG path data in viewBox units (absolute M, L, H, V, C, Z), filled and/or
/// stroked in the current colour.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Shape {
    pub d: &'static str,
    pub fill: bool,
    pub even_odd: bool,
    pub stroke: bool,
    pub stroke_width: f32,
    pub line_cap: LineCap,
    pub line_join: LineJoin,
}

/// A vector drawing: its viewBox and shapes.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Vector {
    pub min_x: f32,
    pub min_y: f32,
    pub width: f32,
    pub height: f32,
    pub shapes: &'static [Shape],
}

${enumOf(
  "Icon",
  t.icons.map((i) => i.name),
  "The icons of the design (decorative: the control around one carries its meaning).",
  `
    /// The icon's geometry.
    pub const fn vector(self) -> &'static Vector {
        match self {
${t.icons.map((i) => `            Icon::${pascal(i.name)} => &ICON_${screaming(i.name)},`).join("\n")}
        }
    }
`,
)}
${t.icons.map((i) => `static ICON_${screaming(i.name)}: Vector = ${rustVector(i)};`).join("\n\n")}

/// The owner's NDDev mark, drawn in the direction's colour; never redrawn.
pub static BRAND_MARK: Vector = ${rustVector(t.mark)};

/// A text style on a platform: family, size, line height as a multiple of the size, weight, letter
/// spacing as a share of the size (em), case.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TextStyle {
    pub family: FontFamily,
    pub size: f32,
    pub line_height: f32,
    pub weight: u16,
    pub tracking: f32,
    pub uppercase: bool,
}

impl TextStyle {
    /// The style of a role on a platform, adjusted for the script of the text.
    pub const fn resolve(role: TypeRole, platform: Platform, script: Script) -> TextStyle {
        let base = Self::base(role, platform);
        TextStyle {
            family: if matches!(base.family, FontFamily::Sans) { script.family() } else { base.family },
            size: base.size,
            line_height: match (role.is_body(), script.body_leading()) {
                (true, Some(leading)) => leading,
                _ => base.line_height,
            },
            weight: base.weight,
            tracking: if script.tracks_letters() { base.tracking } else { 0.0 },
            uppercase: script.has_case() && base.uppercase,
        }
    }

    /// Letter spacing in logical pixels.
    pub fn tracking_px(&self) -> f32 {
        self.tracking * self.size
    }

    const fn base(role: TypeRole, platform: Platform) -> TextStyle {
        match (role, platform) {
${t.type
  .flatMap((r) =>
    t.platforms.map(
      (p) =>
        `            (TypeRole::${pascal(r.role)}, Platform::${pascal(p)}) => TextStyle { family: FontFamily::${family(r.family)}, size: ${f(r.sizes[p] ?? 16)}, line_height: ${f(r.leading)}, weight: ${r.weight}, tracking: ${f(r.tracking)}, uppercase: ${String(r.upper)} },`,
    ),
  )
  .join("\n")}
        }
    }
}
`;
  files.set("src/tokens.rs", `${tokens}\n${rustComponents(t)}`);
  files.set(
    "src/lib.rs",
    `${HEADER}//! The OpenNetwork design tokens: colours per theme and direction, metrics per platform and density,
//! durations per motion, text styles per platform and script. No dependencies, no allocation.
#![no_std]
#![forbid(unsafe_code)]

#[rustfmt::skip]
mod tokens;

pub use tokens::*;
`,
  );

  const first = t.themes[0]?.id ?? "dark";
  const firstDir = t.directions[0]?.id ?? "dev";
  const surface = t.colors.find((c) => c.id === "surface.base")?.values[
    first
  ]?.[firstDir];
  const target = t.dimensions.find((d) => d.id === "size.target-min")?.values[
    "desktop"
  ]?.["comfortable"];
  if (!surface || target === undefined)
    throw new Error("rust tests: surface.base, target-min");
  files.set(
    "tests/tokens.rs",
    `${HEADER}use core::time::Duration;
use nddev_opennetwork_design_tokens::*;

#[test]
fn every_context_resolves() {
    for theme in Theme::ALL {
        for direction in Direction::ALL {
            assert_eq!(Colors::resolve(theme, direction).text_primary.a, 255);
        }
    }
    for platform in Platform::ALL {
        for density in Density::ALL {
            assert!(Metrics::resolve(platform, density).size_target_min > 0.0);
        }
        for role in TypeRole::ALL {
            assert!(TextStyle::resolve(role, platform, Script::Latin).size > 0.0);
        }
    }
}

#[test]
fn values_match_the_tokens() {
    let colors = Colors::resolve(Theme::${pascal(first)}, Direction::${pascal(firstDir)});
    assert_eq!(colors.surface_base.to_rgba(), 0x${hex8(surface).slice(2)}${hex8(surface).slice(0, 2)});
    assert_eq!(
        Metrics::resolve(Platform::Desktop, Density::Comfortable).size_target_min,
        ${f(target)}
    );
    assert_eq!(durations::duration_ui(Motion::Reduced), Duration::ZERO);
}

#[cfg(feature = "fonts")]
#[test]
fn fonts_are_bundled() {
    assert_eq!(font_files::ALL.len(), ${t.bundled.reduce((n, b) => n + b.files.length, 0)});
    for f in &font_files::ALL {
        assert_eq!(&f.data[..4], &[0, 1, 0, 0], "{} is a TrueType file", f.file);
    }
}

#[test]
fn icons_and_mark() {
    assert_eq!(Icon::ALL.len(), ${t.icons.length});
    for icon in Icon::ALL {
        assert!(!icon.vector().shapes.is_empty(), "{}", icon.id());
    }
    assert_eq!(BRAND_MARK.shapes.len(), ${t.mark.shapes.length});
}

#[test]
fn scripts_adjust_styles() {
    let kicker = TextStyle::resolve(TypeRole::Kicker, Platform::Desktop, Script::Latin);
    assert!(kicker.uppercase);
    assert!(kicker.tracking > 0.0);
    let arabic = TextStyle::resolve(TypeRole::Kicker, Platform::Desktop, Script::Arabic);
    assert!(!arabic.uppercase);
    assert_eq!(arabic.tracking, 0.0);
    assert_eq!(arabic.family, FontFamily::SansAr);
    assert_eq!(
        TextStyle::resolve(TypeRole::Code, Platform::Desktop, Script::Arabic).family,
        FontFamily::Mono
    );
}
`,
  );
  files.set(
    "Cargo.toml",
    `${HEADER.replace("//", "#")}[package]
name = "nddev-opennetwork-design-tokens"
version = "${packageInfo.version}"
edition = "2024"
rust-version = "1.85"
description = "The OpenNetwork design tokens: colours, metrics, durations and text styles."
license = "Apache-2.0"
publish = false

[lib]
path = "src/lib.rs"

[features]
# The bundled TTF bytes (font_files::ALL), for renderers that load fonts from memory.
fonts = []
`,
  );
  files.set(
    "rust-toolchain.toml",
    `${HEADER.replace("//", "#")}[toolchain]
channel = "1.99.1"
components = ["clippy", "rustfmt"]
`,
  );
  return files;
}
